693	  }
694	  if duration_ms is Some(value) {
695	    set_field(event, "durationMs", Json::number(value))
696	  }
697	  if attempt is Some(value) {
698	    set_field(event, "attempt", Json::number(value.to_double()))
699	  }
700	  if timeout_ms is Some(value) {
701	    set_field(event, "timeoutMs", Json::number(value.to_double()))
702	  }
703	  if retry_delay_ms is Some(value) {
704	    set_field(event, "retryDelayMs", Json::number(value.to_double()))
705	  }
706	  let failed = error_type is Some(_) ||
707	    ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
708	      status,
709	    )
710	  if diagnostic_pending.length() >= 64 {
711	    let mut evict = -1
712	    if failed {
713	      for index in diagnostic_pending_inflight.val..<diagnostic_pending.length() {
714	        if !diagnostic_pending[index].failed {
715	          evict = index
716	          break
717	        }
718	      }
719	      if evict < 0 &&
720	        diagnostic_pending_inflight.val < diagnostic_pending.length() {
721	        evict = diagnostic_pending_inflight.val
722	      }
723	    }
724	    if evict < 0 {
725	      diagnostic_recording_failed("buffer_full", phase="buffer", event_time~)
726	      return
727	    }
728	    let removed = diagnostic_pending.remove(evict)
729	    diagnostic_pending.push({ event, failed, time: event_time, })
730	    diagnostic_recording_failed(
731	      "buffer_full",
732	      phase="buffer",
733	      event_time=removed.time,
734	    )
735	    try_flush_diagnostic_recording()
736	    return
737	  }
738	  diagnostic_pending.push({ event, failed, time: event_time, })
739	  try_flush_diagnostic_recording()
740	}
