134	///|
135	fn add_protected_secret(secrets : Array[String], value : String) -> Unit {
136	  if value == "" {
137	    return
138	  }
139	  let values = [value]
140	  for part in value.split("\n") {
141	    if part.trim() != "" && part.length() < value.length() {
142	      values.push(part.to_owned())
143	    }
144	  }
145	  for item in values {
146	    if !secrets.contains(item) {
147	      secrets.push(item)
148	    }
149	    let encoded = Json::string(item).stringify()
150	    let escaped = encoded[1:encoded.length() - 1].to_owned()
151	    if escaped != item && !secrets.contains(escaped) {
152	      secrets.push(escaped)
153	    }
154	  }
155	}
