 827	            if read != size.to_int() {
 828	              "short_read"
 829	            } else {
 830	              "incomplete_record"
 831	            },
 832	          )
 833	          set_field(marker, "missingRange", Json::string("unknown"))
 834	          prefix += marker.stringify() + "\n"
