 976	///|
 977	async fn flush_diagnostic_recording() -> Unit {
 978	  if diagnostic_pending.is_empty() && diagnostic_recording_health.dropped == 0 {
 979	    return
 980	  }
 981	  @async.with_timeout(1000, async fn() {
 982	    while !diagnostic_pending.is_empty() ||
 983	          diagnostic_recording_health.dropped > 0 {
 984	      try_flush_diagnostic_recording()
 985	      if !diagnostic_pending.is_empty() ||
 986	        diagnostic_recording_health.dropped > 0 {
 987	        @async.sleep(25)
 988	      }
 989	    }
 990	  }) catch {
 991	    error => if @async.is_being_cancelled() { raise error }
 992	  }
 993	}
