1028	fn diagnostic_error(
1029	  error : Error,
1030	  environment? : Map[String, String],
1031	) -> String {
1032	  let (message, omitted) = match error {
1033	    AdapterError(detail) => (detail, false)
1034	    InvalidConfig(detail) => (detail, false)
1035	    @base64.Malformed(_) => ("Malformed base64 input; input omitted", true)
1036	    @utf8.Malformed(_) => ("Malformed UTF-8 input; input omitted", true)
1037	    @json.InvalidNumber(position, _) =>
1038	      (
1039	        "Invalid JSON number at line \{position.line}, column \{position.column}; value omitted",
1040	        true,
1041	      )
1042	    _ => (error.to_string(), false)
1043	  }
1044	  diagnostic_text(message, environment?, omitted~)
1045	}
