1351	///|
1352	async fn DiagnosticCapture::read(
1353	  self : DiagnosticCapture,
1354	  reader : @process.ReadFromProcess,
1355	) -> Unit {
1356	  try {
1357	    while reader.read_some(max_len=4096) is Some(chunk) {
1358	      let remaining = self.limit - self.output.length()
1359	      let count = if chunk.length() < remaining {
1360	        chunk.length()
1361	      } else {
1362	        remaining
1363	      }
1364	      if count > 0 {
1365	        self.output.write_bytes(chunk[:count])
1366	      }
1367	      if count < chunk.length() {
1368	        self.truncated = true
1369	      }
1370	    }
1371	  } catch {
1372	    error =>
1373	      if @async.is_being_cancelled() {
1374	        raise error
1375	      } else {
1376	        self.truncated = true
1377	      }
1378	  }
1379	  self.finished = true
1380	}
