1383	async fn wait_diagnostic_captures(captures : Array[DiagnosticCapture]) -> Unit {
1384	  @async.with_timeout(250, async fn() {
1385	    while captures.iter().any(capture => !capture.finished) {
1386	      @async.sleep(5)
1387	    }
1388	  }) catch {
1389	    error => if @async.is_being_cancelled() { raise error }
1390	  }
1391	}
