   419	///|
   420	async fn Progress::line(
   421	  self : Progress,
   422	  line : String,
   423	  statuses~ : Bool,
   424	  messages~ : Bool,
   425	) -> Unit {
   426	  if line.trim() == "" {
   427	    return
   428	  }
   429	  let event = @json.parse(line) catch { _ => Json::null() }
   430	  if field(event, "kind") == Some(Json::string("status")) {
   431	    if field(event, "state") == Some(Json::string("failed")) &&
   432	      field(event, "error") is Some(error) {
   433	      for name in ["message", "hint"] {
   434	        if field(error, name) is Some(Json::String(text)) {
   435	          self.message(
   436	            text,
   437	            debug=false,
   438	            warning=true,
   439	            emit=messages || statuses,
   440	          )
   441	        }
   442	      }
   443	    }
   444	    if statuses || messages {
   445	      self.status(event)
   446	    }
   447	    return
   448	  }
   449	  // Result envelopes and arbitrary structured responses are never log text.
   450	  if field(event, "kind") == Some(Json::string("result")) {
   451	    return
   452	  }
   453	  if event is Json::Object(_) {
   454	    let kind = field(event, "kind")
   455	    guard kind == None ||
   456	      kind == Some(Json::string("log")) ||
   457	      kind == Some(Json::string("error")) else {
   458	      return
   459	    }
   460	    let message = match field(event, "msg") {
   461	      Some(value) => Some(value)
   462	      None =>
   463	        match field(event, "message") {
   464	          Some(value) => Some(value)
   465	          None =>
   466	            match field(event, "error") {
   467	              Some(Json::Object(_) as value) => field(value, "message")
   468	              value => value
   469	            }
   470	        }
   471	    }
   472	    guard message is Some(Json::String(text)) else { return }
   473	    let level = field(event, "level")
   474	    self.message(
   475	      text,
   476	      debug=level == Some(Json::string("debug")) ||
   477	        level == Some(Json::string("trace")),
   478	      warning=kind == Some(Json::string("error")) ||
   479	        level == Some(Json::string("warn")) ||
   480	        level == Some(Json::string("error")),
   481	      emit=messages || (statuses && kind != None),
   482	    )
   483	  } else {
   484	    if event != Json::null() {
   485	      return
   486	    }
   487	    // Malformed JSON and binary output are not a safe free-text fallback.
   488	    let text = line.trim().to_owned()
   489	    if text.has_prefix("[ERROR]") || text.has_prefix("[WARN]") {
   490	      self.message(text, debug=false, warning=true, emit=messages)
   491	      return
   492	    }
   493	    if text.has_prefix("{") || text.has_prefix("[") {
   494	      self.details_truncated = true
   495	      return
   496	    }
   497	    self.message(
   498	      text,
   499	      debug=text.contains(" DEBUG ") ||
   500	        text.contains(" TRACE ") ||
   501	        text.has_prefix("DEBUG ") ||
   502	        text.has_prefix("TRACE "),
   503	      warning=text.contains(" WARN ") ||
   504	        text.contains(" ERROR ") ||
   505	        text.has_prefix("WARN ") ||
   506	        text.has_prefix("ERROR "),
   507	      emit=messages,
   508	    )
   509	  }
   510	}
