   538	///|
   539	async fn Progress::read_output(
   540	  self : Progress,
   541	  reader : @process.ReadFromProcess,
   542	  capture~ : Bool,
   543	  statuses~ : Bool = false,
   544	  messages~ : Bool = false,
   545	  raw_messages~ : Bool = false,
   546	) -> String {
   547	  let output = @buffer.Buffer(size_hint=4096)
   548	  let pending = @buffer.Buffer(size_hint=4096)
   549	  let mut oversized = false
   550	  let mut tail = ""
   551	  while reader.read_some(max_len=4096) is Some(chunk) {
   552	    if capture {
   553	      output.write_bytes(chunk)
   554	    } else {
   555	      tail += @utf8.decode_lossy(chunk)
   556	      if tail.length() > 8192 {
   557	        tail = tail[tail.length() - 8192:].to_owned()
   558	      }
   559	    }
   560	    for byte in chunk {
   561	      if byte == b'\n' || byte == b'\r' {
   562	        if !oversized && pending.length() > 0 {
   563	          let line = @utf8.decode(pending.to_bytes()) catch {
   564	            _ => {
   565	              self.details_truncated = true
   566	              ""
   567	            }
   568	          }
   569	          if raw_messages {
   570	            self.message(line, debug=false, warning=true, emit=false)
   571	          } else if capture {
   572	            self.line(line, statuses~, messages~)
   573	          } else {
   574	            self.stderr_line(line, statuses~, messages~)
   575	          }
   576	        }
   577	        pending.reset()
   578	        oversized = false
   579	      } else if !oversized {
   580	        if pending.length() == 65536 {
   581	          pending.reset()
   582	          oversized = true
   583	          self.details_truncated = true
   584	        } else {
   585	          pending.write_byte(byte)
   586	        }
   587	      }
   588	    }
   589	  }
   590	  if !oversized && pending.length() > 0 {
   591	    let line = @utf8.decode(pending.to_bytes()) catch {
   592	      _ => {
   593	        self.details_truncated = true
   594	        ""
   595	      }
   596	    }
   597	    let masked = diagnostic_partial_secret(line, self.secrets)
   598	    if masked != line {
   599	      self.details_truncated = true
   600	    }
   601	    if raw_messages {
   602	      self.message(masked, debug=false, warning=true, emit=false)
   603	    } else if capture {
   604	      self.line(masked, statuses~, messages~)
   605	    } else {
   606	      self.stderr_line(masked, statuses~, messages~)
   607	    }
   608	  }
   609	  if capture {
   610	    @utf8.decode(output.to_bytes())
   611	  } else {
   612	    tail
   613	  }
   614	}
"}}

