 18	///|
 19	async fn server_relay_check(
 20	  state : Json,
 21	  mode : String,
 22	  stage : String,
 23	) -> Json {
 24	  let output = remote(
 25	    state,
 26	    server_update_locked(
 27	      server_update_process_script(
 28	        required(state, "projectRoot"),
 29	        relay_mode=mode,
 30	      ),
 31	    ),
 32	    stage,
 33	  )
 34	  let result = @json.parse(output)
 35	  let outcome = required(result, "outcome")
 36	  guard ["match", "mismatch", "skip", "restart"].contains(outcome) else {
 37	    raise AdapterError("Invalid Orca Server relay comparison")
 38	  }
 39	  let protected_values = if state_recording(state) {
 40	    saved_workspace_secrets(state)
 41	  } else {
 42	    Some([])
 43	  }
 44	  if protected_values is None {
 45	    suppress_workspace_recording(state)
 46	  }
 47	  let progress = Progress::new(
 48	    "server-relay-sync",
 49	    environment=workspace_environment(state),
 50	    protected_secrets?=protected_values,
 51	    protection_incomplete=protected_values is None,
 52	  )
 53	  let evidence : Json = { "outcome": outcome }
 54	  for name in ["serverInstance", "daemonInstance", "relayInstance"] {
 55	    match field(result, name) {
 56	      Some(Json::String(value)) =>
 57	        set_field(
 58	          evidence,
 59	          name,
 60	          Json::string(progress.safe_message(value).unwrap_or("[unavailable]")),
 61	        )
 62	      _ => set_field(evidence, name, Json::null())
 63	    }
 64	  }
 65	  save_diagnostic(
 66	    "server-relay-sync",
 67	    outcome,
 68	    evidence~,
 69	    evidence_incomplete=progress.details_truncated,
 70	    protected_secrets?=protected_values,
 71	    tunnel_directory=required(state, "tunnelDirectory"),
 72	    recording=state_recording(state),
 73	  )
 74	  result
 75	}
