314	fn shell_wait_with_signals(command : String) -> String {
315	  "child=; pending=; " +
316	  "forward() { pending=$1; if test -n \"$child\"; then kill -s \"$pending\" \"$child\" 2>/dev/null || :; fi; }; " +
317	  "trap 'forward TERM' TERM; trap 'forward INT' INT; trap 'forward HUP' HUP; " +
318	  command +
319	  " & child=$!; if test -n \"$pending\"; then kill -s \"$pending\" \"$child\" 2>/dev/null || :; fi; " +
320	  "wait \"$child\"; result=$?; if test -n \"$pending\"; then wait \"$child\" 2>/dev/null || :; fi; " +
321	  "case \"$pending\" in TERM) exit 143 ;; INT) exit 130 ;; HUP) exit 129 ;; esac; exit \"$result\""
322	}
