1393	///|
1394	async fn diagnostic_process_output(
1395	  program : String,
1396	  args : Array[String],
1397	  environment~ : Map[String, String],
1398	  cwd? : StringView,
1399	  stdin? : &@process.ProcessInput,
1400	  stdout_limit~ : Int32,
1401	  stderr_limit~ : Int32,
1402	) -> (Int32, Bytes, Bool, Bytes, Bool) {
1403	  let (out, stdout) = @process.read_from_process()
1404	  defer out.close()
1405	  let (err, stderr) = @process.read_from_process()
1406	  defer err.close()
1407	  @async.with_task_group(async fn(group) {
1408	    let child = @process.spawn(
1409	      group,
1410	      program,
1411	      args,
1412	      extra_env=environment,
1413	      inherit_env=false,
1414	      cwd?,
1415	      stdin?,
1416	      stdout~,
1417	      stderr~,
1418	    )
1419	    let output = DiagnosticCapture::new(stdout_limit)
1420	    let errors = DiagnosticCapture::new(stderr_limit)
1421	    group.spawn_bg(no_wait=true, async fn() { output.read(out) })
1422	    group.spawn_bg(no_wait=true, async fn() { errors.read(err) })
1423	    let status = child.wait()
1424	    while !output.finished {
1425	      @async.sleep(5)
1426	    }
1427	    wait_diagnostic_captures([errors])
1428	    (
1429	      status,
1430	      output.output.to_bytes(),
1431	      output.truncated,
1432	      errors.output.to_bytes(),
1433	      errors.truncated || !errors.finished,
1434	    )
1435	  })
1436	}
