1487	  if text.contains("out of memory") || text.contains("cannot allocate memory") {
1488	    "memory_exhausted"
1489	  } else if text.contains("no space left on device") {
1490	    "disk_exhausted"
1491	  } else if text.contains("address already in use") ||
1492	    text.contains("addrinuse") {
1493	    "address_in_use"
1494	  } else if text.contains("permission denied (publickey") ||
1495	    text.contains("authentication failed") {
1496	    "authentication_failed"
1497	  } else if text.contains("host key verification failed") {
1498	    "host_key_failed"
1499	  } else if text.contains("connection refused") {
1500	    "connection_refused"
1501	  } else if text.contains("connection timed out") ||
1502	    text.contains("operation timed out") {
1503	    "connection_timeout"
1504	  } else if text.contains("could not resolve hostname") {
1505	    "name_resolution"
1506	  } else if text.contains("controlsocket") || text.contains("control socket") {
1507	    "control_socket"
1508	  } else if text.contains("build_vm:") {
1509	    "vm_boot"
1510	  } else if text.contains("create microsandbox vm") && text.contains("network:") {
1511	    "vm_network"
1512	  } else if text.contains("create microsandbox vm") && text.contains("mount:") {
1513	    "vm_mount"
1514	  } else if text.contains("ensure microsandbox final image") ||
