1516	    "vm_image"
1517	  } else if text.contains("create microsandbox vm") {
1518	    "vm_create"
1519	  } else if text.contains("start microsandbox vm") {
1520	    "vm_start"
1521	  } else if text.contains("no such file or directory") ||
1522	    text.contains("not found") {
