    78	async fn recover_server(
    79	  state : Json,
    80	  connection_result~ : Bool = false,
    81	) -> Json {
    82	  let directory = required(state, "tunnelDirectory")
    83	  let lock = @fs.open(
    84	    directory + "/server.lock",
    85	    mode=ReadWrite,
    86	    create_mode=OpenOrCreate,
    87	    permission=0o600,
    88	  )
    89	  defer lock.close()
    90	  @async.with_timeout(30000, async fn() {
    91	    while !lock.try_lock(Exclusive) {
    92	      @async.sleep(100)
    93	    }
    94	  })
    95	  guard @fs.exists(directory + "/enabled") && !@fs.exists(directory + "/paused") else {
    96	    raise AdapterError("Connection recovery cancelled")
    97	  }
    98	  guard !@fs.exists(directory + "/server-update-pending") else {
    99	    raise AdapterError("Server update is incomplete; retry the update")
   100	  }
   101	  let pending = directory + "/server-relay-pending"
   102	  errdefer save_diagnostic(
   103	    "server-relay-sync",
   104	    "failed",
   105	    error_type="sync_failed",
   106	    tunnel_directory=directory,
   107	    recording=state_recording(state),
   108	  )
   109	  let mut output = if !connection_result && server_is_running(state) {
   110	    save_diagnostic(
   111	      "recover-server",
   112	      "reuse",
   113	      tunnel_directory=directory,
   114	      recording=state_recording(state),
   115	    )
   116	    Json::null()
   117	  } else {
   118	    save_diagnostic(
   119	      "recover-server",
   120	      "start",
   121	      tunnel_directory=directory,
   122	      recording=state_recording(state),
   123	    )
   124	    if field(state, "orcaVolume") is Some(_) {
   125	      prepare_orca_storage(state)
   126	      let installation = remote(
   127	          state, "if test -x \"$HOME/.local/share/orca-env-devsy/orca/current/orca-ide\"; then printf installed; else printf missing; fi",
   128	          "orca-install-probe",
   129	        )
   130	        .trim()
   131	        .to_owned()
   132	      match installation {
   133	        "installed" => ()
   134	        "missing" =>
   135	          ignore(remote(state, server_install_script(), "orca-install"))
   136	        _ => raise AdapterError("Invalid Orca installation probe result")
   137	      }
   138	    }
   139	    let launched = launch_server(state)
   140	    configure_orca_project(state)
   141	    launched
   142	  }
   143	  let observed = server_relay_check(
   144	    state,
   145	    if @fs.exists(pending) {
   146	      "verify-required"
   147	    } else {
   148	      "verify"
   149	    },
   150	    "server-relay-check",
   151	  )
   152	  let mut outcome = required(observed, "outcome")
   153	  if outcome == "mismatch" {
   154	    @fs.write_file(pending, "", permission=0o600)
   155	    let stopped = server_relay_check(state, "sync", "server-relay-stop")
   156	    outcome = required(stopped, "outcome")
   157	    guard field(observed, "relayInstance") == field(stopped, "relayInstance") else {
   158	      raise AdapterError("Orca relay instance changed during recovery")
   159	    }
   160	    if outcome == "restart" {
   161	      output = launch_server(state)
   162	      let verified = server_relay_check(
   163	        state, "verify-required", "server-relay-verify",
   164	      )
   165	      guard (
   166	          required(verified, "outcome") == "match" ||
   167	          (
   168	            required(verified, "outcome") == "skip" &&
   169	            field(stopped, "serverInstance") == Some(Json::string(""))
   170	          )
   171	        ) &&
   172	        field(stopped, "relayInstance") == field(verified, "relayInstance") else {
   173	        raise AdapterError(
   174	          "Orca relay instance changed or is unavailable after restart",
   175	        )
   176	      }
   177	      save_diagnostic(
   178	        "server-relay-sync",
   179	        "restarted",
   180	        tunnel_directory=directory,
   181	        recording=state_recording(state),
   182	      )
   183	    }
   184	  }
   185	  guard outcome == "restart" || outcome == "match" || outcome == "skip" else {
   186	    raise AdapterError("Cannot compare Orca relay instances")
   187	  }
   188	  if @fs.exists(pending) {
   189	    @fs.remove(pending)
   190	  }
   191	  @fs.write_file(directory + "/server-enabled", "", permission=0o600)
   192	  output
   193	}
