305	///|
306	async fn update_one_server(
307	  state : Json,
308	  provider : String,
309	  version : String,
310	  force : Bool,
311	) -> Json {
312	  let directory = required(state, "tunnelDirectory")
313	  let result : Json = {
314	    "id": required(state, "workspaceId"),
315	    "provider": provider,
316	    "context": required(state, "context"),
317	    "targetVersion": version,
318	    "outcome": "failed",
319	  }
320	  let mut phase = "identity"
350	    if status == "Stopped" {
351	      set_field(result, "outcome", Json::string("skipped"))
352	      set_field(result, "reason", Json::string("workspace_stopped"))
353	      save_diagnostic(
354	        "server-update",
355	        "skipped",
356	        evidence=result,
357	        protected_secrets=secrets,
358	        environment=workspace_environment(state),
359	        tunnel_directory=directory,
360	        recording=operation_recording(state),
361	      )
362	      return result
363	    }
364	    guard status == "Running" else {
365	      raise AdapterError("Workspace is not running")
366	    }
367	    phase = "transport"
368	    ensure_ssh_worker(state, Some(reserve_server_port(state)))
369	    let lock = @fs.open(
370	      directory + "/server.lock",
371	      mode=ReadWrite,
372	      create_mode=OpenOrCreate,
373	      permission=0o600,
374	    )
375	    defer lock.close()
376	    @async.with_timeout(30000, async fn() {
377	      while !lock.try_lock(Exclusive) {
378	        @async.sleep(100)
379	      }
380	    })
381	    if @fs.exists(directory + "/server-update-complete") {
382	      cleanup_server_update(state)
383	    }
384	    let pending = @fs.exists(directory + "/server-update-pending")
385	    set_field(result, "retry", Json::boolean(pending))
386	    phase = "version"
387	    let installed = update_remote(
388	        state, "base=\"$HOME/.local/share/orca-env-devsy/orca\"; dir=\"$base/current\"; if test ! -x \"$dir/orca-ide\"; then dir=\"$base/update-previous\"; fi; ELECTRON_RUN_AS_NODE=1 \"$dir/orca-ide\" \"$dir/resources/app.asar/out/cli/index.js\" --version",
389	        "server-update-version",
390	      )
391	      .trim()
392	      .to_owned()
393	    ignore(server_version(installed))
394	    set_field(result, "previousVersion", Json::string(installed))
395	    if server_version_is_older(version, installed) && !force {
396	      raise AdapterError("Server downgrade requires --force")
397	    }
398	    phase = "prepare"
399	    if !pending {
400	      ignore(
401	        update_remote(
402	          state, "test ! -e \"$HOME/.local/share/orca-env-devsy/orca/update-previous\" && test ! -e \"$HOME/.local/share/orca-env-devsy/orca/update-retry\"",
403	          "server-update-ownership",
404	        ),
405	      )
406	    }
407	    ignore(
408	      update_remote(
409	        state,
410	        server_update_prepare_script(version),
411	        "server-update-prepare",
412	      ),
413	    )
414	    phase = "identity-recheck"
415	    let current = workspace(state)
416	    guard current is Some(current) &&
417	      field(current, "uid") == field(state, "workspaceUid") &&
418	      field(field(current, "provider").unwrap_or(Json::null()), "name") ==
419	      Some(Json::string(provider)) &&
420	      workspace_status(state) == "Running" else {
421	      raise AdapterError("Workspace changed before Server update")
422	    }
423	    @fs.write_file(
424	      directory + "/server-update-pending",
425	      version,
426	      permission=0o600,
427	    )
428	    phase = "stop"
429	    ignore(
430	      update_remote(
431	        state,
432	        server_update_process_script(required(state, "projectRoot")),
433	        "server-update-stop",
434	      ),
435	    )
436	    phase = "switch"
437	    ignore(
438	      update_remote(
439	        state,
440	        server_update_swap_script(version),
441	        "server-update-switch",
442	      ),
443	    )
444	    phase = "start"
445	    let launch_id = version +
446	      ":" +
447	      recording_run_id +
448	      ":" +
449	      required(state, "workspaceUid")
450	    let mut marker_name = "ORCA_ENV_DEVSY_UPDATE_" + recording_run_id
451	    while field(
452	            field(state, "serverEnv").unwrap_or(Json::empty_object()),
453	            marker_name,
454	          )
455	          is Some(_) {
456	      marker_name = marker_name + "_"
457	    }
458	    ignore(launch_server(state, update_marker=(marker_name, launch_id)))
459	    phase = "verify"
460	    let actual = update_remote(
461	        state, "base=\"$HOME/.local/share/orca-env-devsy/orca/current\"; ELECTRON_RUN_AS_NODE=1 \"$base/orca-ide\" \"$base/resources/app.asar/out/cli/index.js\" --version",
462	        "server-update-verify-version",
463	      )
464	      .trim()
465	      .to_owned()
466	    guard actual == version else {
467	      raise AdapterError("Updated Server version does not match Desktop")
468	    }
469	    @async.with_timeout(15000, async fn() {
470	      while !server_is_running(state) {
471	        @async.sleep(200)
472	      }
473	    })
474	    ignore(
475	      update_remote(
476	        state,
477	        server_update_process_script(
478	          required(state, "projectRoot"),
479	          version=marker_name + "=" + launch_id,
480	        ),
481	        "server-update-verify-owner",
482	      ),
483	    )
484	    phase = "commit"
485	    @fs.rename(
486	      directory + "/server-update-pending",
487	      directory + "/server-update-complete",
488	      replace=true,
489	    )
490	    cleanup_server_update(state) catch {
491	      error =>
492	        set_field(
493	          result,
494	          "cleanupWarning",
495	          Json::string(workspace_error_detail(state, error)),
496	        )
497	    }
498	    set_field(result, "outcome", Json::string("success"))
499	    save_diagnostic(
500	      "server-update",
501	      "success",
502	      evidence=result,
503	      protected_secrets=secrets,
504	      environment=workspace_environment(state),
505	      tunnel_directory=directory,

