+///|
+async test "remote server launch forwards cancellation signals to the serve process" {
+  for configured in [false, true] {
+    for update in [false, true] {
+      for signal in ["TERM", "INT"] {
+        let directory = @fs.tmpdir(prefix="orca-env-devsy-server-signal")
+        defer cleanup_fixture(directory)
+        let install = directory + "/.local/share/orca-env-devsy/orca/current"
+        @fs.mkdir(install + "/resources/app.asar/out/cli", recursive=true)
+        let bun = command(
+            "which",
+            ["bun"],
+            "fixture-bun",
+            recording_override=false,
+          )
+          .trim()
+          .to_owned()
+        @fs.symlink(install + "/orca-ide", target=bun)
+        let executable =
+          #|const fs = require("fs");
+          #|for (const s of ["SIGTERM", "SIGINT"]) process.on(s, () => { fs.writeFileSync(process.env.HOME + "/signal", s); process.exit(0); });
+          #|fs.writeFileSync(process.env.HOME + "/serve-pid", String(process.pid));
+          #|setInterval(() => {}, 1000);
+        @fs.write_file(
+          install + "/resources/app.asar/out/cli/index.js",
+          executable,
+        )
+        defer @async.protect_from_cancel(async fn() {
+          if @fs.exists(directory + "/serve-pid") {
+            let pid = @string.parse_int(
+              @fs.read_file(directory + "/serve-pid").text(),
+            )
+            if process_start(pid) > 0 {
+              ignore(proxy_signal(pid, 9))
+            }
+          }
+        })
+        let env = @env.get_env_vars()
+        env.set("HOME", directory)
+        let config : Json = if configured {
+          { "COPY": "literal" }
+        } else {
+          Json::empty_object()
+        }
+        let launch = server_launch_script(directory, 12345, config)
+        let script = if update {
+          server_update_locked(launch, inline_launch=true)
+        } else {
+          launch
+        }
+        @async.with_timeout(5000, async fn() {
+          @async.with_task_group(async fn(group) {
+            let sink = @process.redirect_to_file("/dev/null", shared=true)
+            defer sink.close()
+            let child = @process.spawn(
+              group,
+              "sh",
+              ["-c", script],
+              extra_env=env,
+              stdout=sink,
+              stderr=sink,
+            )
+            idle_wait_for(async fn() { @fs.exists(directory + "/serve-pid") })
+            assert_eq(
+              @process.run("kill", ["-" + signal, child.pid.to_string()]),
+              0,
+            )
+            assert_eq(child.wait(), if signal == "TERM" { 143 } else { 130 })
+            assert_eq(
+              @fs.read_file(directory + "/signal").text(),
+              "SIG" + signal,
+            )
+            let pid = @string.parse_int(
+              @fs.read_file(directory + "/serve-pid").text(),
+            )
+            idle_wait_for(() => process_start(pid) == 0)
+            if update {
+              assert_false(
+                @fs.exists(
+                  directory + "/.local/share/orca-env-devsy/orca/update-active",
+                ),
+              )
+            }
+          })
+        })
+      }
+    }
+  }
