  2	fn parse_idle_timeout(value : String) -> Int64 raise ConfigError {
  3	  let (digits, scale) = if value.has_suffix("s") {
  4	    (value[:value.length() - 1].to_owned(), 1000L)
  5	  } else if value.has_suffix("m") {
  6	    (value[:value.length() - 1].to_owned(), 60000L)
  7	  } else if value.has_suffix("h") {
  8	    (value[:value.length() - 1].to_owned(), 3600000L)
  9	  } else if value.has_suffix("d") {
 10	    (value[:value.length() - 1].to_owned(), 86400000L)
 11	  } else {
 12	    raise InvalidConfig(
 13	      "idleTimeout must be a positive integer followed by s, m, h or d",
 14	    )
 15	  }
 16	  guard digits != "" && digits.to_array().iter().all(c => c >= '0' && c <= '9') else {
 17	    raise InvalidConfig("Invalid idleTimeout duration")
 18	  }
 19	  let amount = @string.parse_int64(digits) catch {
 20	    _ => raise InvalidConfig("idleTimeout is too large")
 21	  }
 22	  guard amount > 0 && amount <= 9007199254740991L / scale else {
 23	    raise InvalidConfig(
 24	      "idleTimeout must be positive and exactly representable",
 25	    )
 26	  }
